from collections import deque

def find_connected_components(grid):
    colors = {v: set() for v in set(cell for row in grid for cell in row)}
    visited = set()
    comp_id = 0

    for r in range(height):
        for c in range(width):
            if (r, c) not in visited and grid[r][c] == 2:
                comp = set()
                queue = deque([(r, c)])
                visited.add((r, c))
                comp.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == 2 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            comp.add((nr, nc))
                            queue.append((nr, nc))
                colors[2] = comp  # track 2s
                comp_id += 1
    return colors

